test_suite:
test('pickKeys selects specified keys', () => {
  const user = { id: 1, name: 'Alice', email: 'a@x.com' };
  expect(pickKeys(user, ['id', 'name'])).toEqual({ id: 1, name: 'Alice' });
});

test('pickKeys excludes unselected keys', () => {
  const obj = { a: 1, b: 2, c: 3 };
  const result = pickKeys(obj, ['a', 'c']);
  expect('b' in result).toBe(false);
});

test('type-level: MyPick matches built-in Pick', () => {
  type T = { x: number; y: string; z: boolean };
  type Check = MyPick<T, 'x' | 'y'> extends Pick<T, 'x' | 'y'> ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});

// __hidden__
test('pickKeys with single key', () => {
  const data = { foo: 'bar', baz: 42 };
  expect(pickKeys(data, ['foo'])).toEqual({ foo: 'bar' });
});

solution:
export type MyPick<T, K extends keyof T> = { [P in K]: T[P] };

export function pickKeys<T, K extends keyof T>(obj: T, keys: K[]): MyPick<T, K> {
  const result = {} as MyPick<T, K>;
  for (const key of keys) {
    result[key] = obj[key];
  }
  return result;
}
